          "title": "把“先努力再休息”读成“一卡住就休息”",
          "text": "官方给发散模式的用法有明确顺序：先真的下功夫解决问题，然后再休息让潜意识接管。一卡住就立刻休息、去刷手机，不是发散模式，就是它列的第一个坑——拖延。"
