            "官方的态度很明确：作业本来就该由你自己想清楚怎么解决，而“想出解法思路”正是你学习旅程中必不可少的部分。更好的问法长这样：“嗨，我在试着返回一个显示 Rock Paper Scissors 胜者的字符串，但第 12 行报了语法错误。我要怎么修？这是我的代码。”",
