            "官方还建议：把你的伪代码（pseudo code）分享出来，这样别人可以把你推向正确方向，或者纠正你可能有的误解。伪代码不是编程语言，是用自然话写的步骤草稿——它恰好能让别人看出你的思路在哪一步偏了。"
