            "路由器（router）：转发网络数据的设备。数据包每到一个路口，由路由器决定下一跳往哪边走，一站站接力传向目的地。你家那个闪着灯的盒子就是一台小路由器。",
            "ISP（Internet Service Provider，互联网服务提供商）：你付费上网的那家运营商（电信、联通、移动这类公司）。它为你提供了接入互联网的入口，你的家庭网络通过 ISP 连进更大的互联网。"
