            "为什么要这么麻烦？因为这样最高效也最可靠：线路由所有通信共享，没有哪个大文件能长期独占一条链路；某个包在路上丢了或损坏了，只需要重传那一个包，而不是整个文件。官方对这一课的要求就是理解“数据包是什么、如何用它们传输数据”，不需要深入协议格式。"
