            "把 <p> 拆开读：尖括号 < > 是包住关键字的“界标”，p 是英文单词 paragraph（段落）的首字母；</p> 里的 /（斜杠）可以理解成“关闭、结束”——看到斜杠就知道这是结束标签。很多标签的关键字都是英文单词的缩写，记标签时顺带记住英文全称，也正是第 1 课建议的英语术语积累方式。"
