            "这就是 HTML 名字里“标记（Markup）”的含义：你不是在写内容长什么样，而是在给内容贴“它是什么”的标记；具体怎么显示，交给浏览器和后面要学的 CSS 决定。",
            "给自己一个记忆锚点：标签是“两侧的界标”，内容是“中间的主体”，元素是从开始标签到结束标签的完整整体。要能脱口答出“HTML 元素的三个部分是哪三个”，答案就是上一节拆解的三条：开始标签、内容、结束标签——注意别漏掉“内容”，只答出两个标签。",
