            "用对标签的影响主要在两个方面：一是你的站点在搜索引擎里的排名——搜索引擎靠标签理解页面内容的结构；二是可访问性——依赖辅助技术（比如屏幕阅读器）上网的用户，是靠标签“听”懂页面的。标签用错，这两方面都会受损。",
            "给内容使用正确的元素，官方称之为语义化 HTML（semantic HTML），课程后面会深入展开。现阶段你只需要种下这个习惯：写标签前先想一下“这段内容是什么”——是段落、标题，还是列表——再选对应的标签。",
            "这个习惯在后面的课里会逐渐具体化：同样一句文字，用 <p> 包住，浏览器、搜索引擎和屏幕阅读器就都知道“这是正文的一个段落”。标签的价值不在于让页面上的字好看，而在于让所有读页面的“人”和程序都明白这段内容是什么。"
