            "官方说这一课会学怎样创建链接，以及怎样通过嵌入图片给网站加一点视觉光彩。学习目标有四条：怎样创建到互联网上其他网站页面的链接；怎样创建到你自己网站上其他页面的链接；绝对链接与相对链接的区别；怎样用 HTML 在网页上显示一张图片。"
