            "官方让你把 <a>About The Odin Project</a> 加到 index.html 的 body 里，并在浏览器打开它。然后官方指出一个现象：你可能已经注意到，点击这个链接什么也不会发生。",
            "官方的解释是：这是因为单独一个 anchor 标签不知道我们想链接到哪里。我们必须告诉它一个要去的目的地，而这是通过一个 HTML 属性做到的。"
