            "官方说，在我们的情况里，需要给 anchor 的开始标签加一个 href（hypertext reference，超文本引用）属性。href 属性的值，就是我们想让链接去的目的地。",
            "官方让你把 href 属性加到刚才创建的 anchor 元素上，然后再试着点它——并且提醒：别忘了刷新浏览器，好让新的改动能生效。官方给的示例链接到 TOP 的 About 页面。",
            "官方还说明了视觉反馈：默认情况下，任何被 anchor 标签包住、但没有 href 属性的文字，看起来会像普通文本。如果 href 属性存在，浏览器会给文字加上蓝色并加下划线，以表明它是一个链接。",
            "官方补了一句：值得一提的是，你可以用 anchor 标签链接到互联网上任何类型的资源，不只是其他 HTML 文档。你可以链接到视频、pdf 文件、图片等等，但大多数时候你链接的会是其他 HTML 文档。"
