            "官方解释了两者的分工：href 指定目的地链接，而 target 指定被链接的资源将在哪里打开。如果 target 不存在，那么默认情况下它会取 _self 这个值，也就是在当前标签页打开链接。要在新标签页或新窗口里打开链接（取决于浏览器设置），你可以把它设为 _blank。"
