            "第一种叫绝对链接（absolute links）。官方说一个典型的绝对链接由这几部分组成：scheme://domain/path。绝对链接总是会包含目的地的 scheme（协议）和 domain（域名），官方为此链接了 MDN 关于 URL 结构的说明。",
            "官方指出你已经见过一个绝对链接了：我们前面创建的、指向 The Odin Project About 页面的链接就是绝对链接，因为它包含 scheme 和域名，也就是 https://www.theodinproject.com/about。"
