          "code": "/* rule 1 */\n.subsection {\n  color: blue;\n}\n\n/* rule 2 */\n.main .list {\n  color: red;\n}",
          "note": "两条都只用类选择器，但 rule 2 用了两个类，所以 color: red 生效。"
