      "note": "",
      "why": "CSS 里最重要的两件事是定位（positioning）与布局（layout）——能把元素放到你想要的位置上，比调字体颜色关键得多。而这两件事的地基就是盒模型：不理解每个元素「实际占了多大一块地方」，后面调任何尺寸都是猜。很多学习者急着冲去学 JavaScript，恰恰在这一课留下窟窿，之后写样式时处处碰壁。",
