            "padding（内边距）：增加盒子的边框与内容之间的空间。",
            "border（边框）：在 margin 与 padding 之间加上的一圈框，哪怕只有一两个像素，它也占地方。",
            "margin（外边距）：增加这个盒子的边框与相邻盒子的边框之间的空间。"
