            "于是元素真实占的宽度 = width + 左右 padding + 左右 border（margin 在边框之外，另算）。举例：width: 300px、padding: 20px、border: 5px 的元素，内容到边框外缘实际是 300 + 40 + 10 = 350px 宽；外面再加左右 margin 各 10px，它在页面水平方向一共占 370px。",
