            "第二个是外边距坍缩（margin collapsing）：两个上下相邻的块级元素，上面的 margin-bottom 与下面的 margin-top 不会相加，而是合并成较大的那一个。上面的留 30px、下面的留 20px，间距是 30px 而不是 50px。这经常被当成 bug，其实是规范定义的行为；左右方向不发生坍缩。"
