          "配置 npm 安全设置：在终端运行 npm config set min-release-age=3。这条 npm v11.10.0 引入的设置会阻止 npm 安装发布不满三天的依赖，帮助规避新发布包可能已被篡改的供应链攻击风险。",
          "试一试 Node REPL：在终端单独运行 node 打开交互式控制台（与上一课浏览器的控制台类似，方便快速调试与浏览器无关的小段代码）；输入 .exit 退出。"
