          "answer": "map 对每个元素跑回调、返回结果组成的新数组（长度不变、值被转换）；filter 按回调返回真假筛选、返回子集新数组（长度可能变、值不变）；reduce 把整个数组用回调累积成单个值（数字、字符串、什么都可以）。三个都**不改原数组**——都返回新东西。"
