          "answer": "点号写法里 JS 会把连字符当成减号，相当于「div.style.background 减 color」。改用 div.style.backgroundColor（点号 + camelCase）或 div.style[\"background-color\"]（方括号字符串，kebab-case / camelCase 都行）。"
